STATUS_MAP = {"done": "done", "partial": "done", "not_done": "not_done"}


def _migrate_recurrences() -> None:
    """Cada tarea recurrente pasa a ser un 'hábito que ya tienes' con su historial.
    Hecho y A medias cuentan como Hecho; No hecho como No hecho; pendientes y pospuestas no dejan registro."""
    bind = op.get_bind()
    now = datetime.utcnow()
    recs = bind.execute(sa.text(
        "SELECT id, user_id, title, category_id, time, weekdays, start_date, is_active FROM task_recurrences"
    )).mappings().all()
    for r in recs:
        habit_id = str(uuid.uuid4())
        bind.execute(sa.text(
            "INSERT INTO habits (id, user_id, title, category_id, time, weekdays, kind, status, start_date, "
            "period_days, target_rate, result_notified, adjustments, position, created_at, updated_at) "
            "VALUES (:id, :user_id, :title, :category_id, :time, :weekdays, 'established', :status, :start_date, "
            "NULL, 0.8, :false, 0, 0, :now, :now)"
        ), {**dict(r), "id": habit_id, "status": "active" if r["is_active"] else "archived", "false": False, "now": now})
        items = bind.execute(sa.text(
            "SELECT date, status FROM task_items WHERE recurrence_id = :rid AND is_deleted = :false AND date IS NOT NULL"
        ), {"rid": r["id"], "false": False}).mappings().all()
        for it in items:
            status = STATUS_MAP.get(it["status"])
            if status:
                bind.execute(sa.text(
                    "INSERT INTO habit_logs (id, habit_id, user_id, date, status, created_at, updated_at) "
                    "VALUES (:id, :habit_id, :user_id, :date, :status, :now, :now)"
                ), {"id": str(uuid.uuid4()), "habit_id": habit_id, "user_id": r["user_id"], "date": it["date"], "status": status, "now": now})
    # Las instancias recurrentes ya no son tareas (las copias pospuestas quedan como tareas sueltas)
    bind.execute(sa.text(
        "UPDATE task_items SET postponed_from_id = NULL WHERE postponed_from_id IN "
        "(SELECT id FROM (SELECT id FROM task_items WHERE recurrence_id IS NOT NULL) AS r)"
    ))
    bind.execute(sa.text("DELETE FROM task_items WHERE recurrence_id IS NOT NULL"))
    bind.execute(sa.text("UPDATE task_recurrences SET is_active = :false"), {"false": False})
